            introductionBn = "ক্যাথেটারজনিত সংক্রমণ (CAUTI) প্রতিরোধ এবং কিডনি রোগে ফ্লুইড, পটাশিয়াম ও AV ফিস্টুলা রক্ষা করা প্রধান নার্সিং দায়িত্ব।",
            causesRiskEn = "• UTI: E. coli (80%), indwelling Foley catheter, female anatomy, urinary retention, DM.\n• CKD: Diabetic nephropathy (#1), hypertension (#2), glomerulonephritis, polycystic kidney disease.",
            causesRiskBn = "• UTI: ই. কোলাই, ফোলি ক্যাথেটার, ডায়াবেটিস।\n• CKD: ডায়াবেটিস (১ম কারণ) ও উচ্চ রক্তচাপ (২য় কারণ)।",
            signsSymptomsEn = "• UTI: Dysuria, urgency, frequency, suprapubic pain; Pyelonephritis: fever, chills, CVA flank tenderness; elderly: acute confusion!\n• CKD: Oliguria, edema, hypertension, uremic frost, pruritus, fatigue (anemia), metallic taste.",
            signsSymptomsBn = "• UTI: প্রস্রাবে জ্বালাপোড়া, ঘন ঘন প্রস্রাব; পাইলোনেফ্রাইটিসে জ্বর ও কোমরে ব্যথা; বয়স্কদের হঠাৎ বিভ্রান্তি।\n• CKD: প্রস্রাব কমে যাওয়া, শরীরে পানি জমা, রক্তস্বল্পতা, চুলকানি।",
            pathophysiologyEn = "CKD: Loss of nephrons -> decreased GFR -> accumulation of urea/creatinine (uremia), hyperkalemia, metabolic acidosis, low erythropoietin (anemia), and impaired Vitamin D activation.",
            pathophysiologyBn = "নেফ্রন ধ্বংস হয়ে ইউরিয়া/ক্রিয়েটিনিন জমে, পটাশিয়াম বাড়ে, অ্যাসিডোসিস ও অ্যানিমিয়া হয়।",
            assessmentEn = "Daily weight (best fluid indicator!), strict I&O, lung crackles, peripheral edema, AV fistula thrill (palpate) & bruit (auscultate), urine color/clarity.",
            assessmentBn = "দৈনিক ওজন (ফ্লুইড মাপার সেরা উপায়), I&O চার্ট, ফুসফুসের শব্দ, AV ফিস্টুলার থ্রিল ও ব্রুইট পরীক্ষা।",
            investigationsEn = "Urinalysis (nitrites, leukocyte esterase) & urine culture; serum creatinine, BUN, eGFR, electrolytes (K+, Ca++, PO4), renal ultrasound.",
            investigationsBn = "প্রস্রাব রুটিন ও কালচার; ক্রিয়েটিনিন, eGFR, ইলেক্ট্রোলাইট (পটাশিয়াম) ও আল্ট্রাসাউন্ড।",
            medicalManagementEn = "• UTI: Targeted antibiotics (Nitrofurantoin, Ciprofloxacin, Ceftriaxone), remove unnecessary catheters.\n• CKD: ACEi/ARB, loop diuretics, potassium binders, phosphate binders, Erythropoietin (EPO), hemodialysis/peritoneal dialysis.",
            medicalManagementBn = "• UTI: কালচার অনুযায়ী অ্যান্টিবায়োটিক, অপ্রয়োজনীয় ক্যাথেটার খোলা।\n• CKD: রক্তচাপ নিয়ন্ত্রণ, পটাশিয়াম/ফসফেট নিয়ন্ত্রণ, ইরিথ্রোপয়েটিন ও ডায়ালাইসিস।",
            nursingManagementEn = "• UTI: Increase fluids (2–3 L/day unless contraindicated), wipe front-to-back, strict sterile catheter care.\n• CKD: Fluid restriction, low-K+/low-Na+/low-phosphate diet; NEVER take BP, draw blood, or start IV in an AV fistula arm! Hold dialyzable meds before hemodialysis.",
            nursingManagementBn = "• UTI: পর্যাপ্ত পানি, সামনে থেকে পেছনে পরিষ্কার ও ক্যাথেটার জীবাণুমুক্ত রাখা।\n• CKD: AV ফিস্টুলার হাতে কখনোই BP, ব্লাড ড্র বা ক্যানুলা দেবেন না; ডায়ালাইসিসের আগে নির্দিষ্ট ওষুধ স্থগিত রাখুন।",
            interventionsRationaleEn = "• Weigh CKD patient daily at same time -> 1 kg weight gain ≈ 1 liter fluid retention.\n• Check thrill & bruit every shift -> Confirms AV fistula patency.",
            interventionsRationaleBn = "• প্রতিদিন একই সময়ে ওজন মাপা -> ১ কেজি ওজন বাড়া মানে ~১ লিটার পানি জমা।\n• প্রতি শিফটে ফিস্টুলার থ্রিল-ব্রুইট দেখা।",
            complicationsEn = "Urosepsis, acute kidney injury; CKD: fatal hyperkalemia (peaked T waves!), pulmonary edema, uremic encephalopathy.",
            complicationsBn = "ইউরোসেপসিস, মারাত্মক হাইপারক্যালেমিয়া, পালমোনারি এডিমা।",
            preventionEn = "Remove Foley catheters as early as possible; control diabetes and BP.",
            preventionBn = "দ্রুত ক্যাথেটার অপসারণ এবং ডায়াবেটিস-রক্তচাপ নিয়ন্ত্রণ।",
            patientEducationEn = "Complete full UTI antibiotic course; CKD patients avoid NSAIDs and potassium-rich salt substitutes.",
            patientEducationBn = "UTI-এর অ্যান্টিবায়োটিক কোর্স শেষ করুন; CKD রোগীরা ব্যথানাশক NSAID এড়িয়ে চলুন।",
            nursingNotesEn = "Exam Pearl: In older adults, sudden new-onset confusion/delirium is often the FIRST sign of a UTI! Avoid nephrotoxic drugs (Aminoglycosides, NSAIDs, contrast dye) in CKD.",
            nursingNotesBn = "পরীক্ষার নোট: বয়স্কদের হঠাৎ বিভ্রান্তি প্রায়ই UTI-এর প্রথম লক্ষণ! কিডনি রোগে NSAID বর্জনীয়।",
            sourceTitle = "KDIGO CKD Clinical Guidelines & IDSA UTI Guidelines",
            sourceUrl = "https://kdigo.org",
            publishedDate = "2024-11-22",
            verificationStatus = "Verified",
            emergencyFlag = "Red Flag: Hyperkalemia (K+ > 6.0 mEq/L with peaked T waves), pulmonary edema, or urosepsis requires emergency dialysis or stabilization."
