            medicalManagementEn = "Treat underlying cause; Ferrous sulfate PO (or IV iron sucrose); Vitamin B12 IM lifelong for pernicious anemia; Folic acid; PRBC transfusion only if severe/symptomatic.",
            medicalManagementBn = "মূল কারণের চিকিৎসা, মুখে বা IV আয়রন, পার্নিসিয়াস অ্যানিমিয়ায় B12 ইনজেকশন ও ফলিক অ্যাসিড।",
            nursingManagementEn = "Give oral iron on empty stomach with Vitamin C (orange juice) for absorption; avoid giving iron with milk, tea, coffee, or antacids! Use Z-track for IM iron (if ever ordered); alternate rest with activity.",
