            keywords = "pressure ulcer bed sore braden scale decubitus wound healing staging বেড সোর ক্ষত প্রেসার আলসার",
            definitionEn = "A Pressure Injury (Bed Sore / Decubitus Ulcer) is localized damage to skin and/or underlying soft tissue, usually over a bony prominence (sacrum, heels, trochanters), caused by intense or prolonged pressure with shear.",
            definitionBn = "প্রেসার ইনজুরি বা বেড সোর হলো হাড়ের উঁচু অংশের ওপর দীর্ঘক্ষণ চাপ ও ঘর্ষণের ফলে ত্বক ও নিচের টিস্যুর স্থানীয় ক্ষতি।",
            introductionEn = "Hospital-acquired pressure injuries are largely preventable nursing-sensitive quality indicators requiring Braden Scale screening and 2-hourly repositioning.",
            introductionBn = "নিয়মিত অবস্থান পরিবর্তন ও ব্রেডেন স্কেল মূল্যায়নের মাধ্যমে বেড সোর প্রতিরোধ করা যায়।",
            causesRiskEn = "Immobility, friction & shear, moisture (incontinence), poor nutrition/low albumin, impaired sensory perception (spinal injury, coma), advanced age.",
            causesRiskBn = "দীর্ঘদিন নড়াচড়া না করা, ঘর্ষণ, আর্দ্রতা, অপুষ্টি, সংবেদনহীনতা।",
            signsSymptomsEn = "Staging:\n• Stage 1: Non-blanchable erythema of intact skin.\n• Stage 2: Partial-thickness dermis loss (blister/shallow pink crater).\n• Stage 3: Full-thickness skin loss (subcutaneous fat visible).\n• Stage 4: Full-thickness tissue loss with exposed bone, tendon, or muscle.\n• Unstageable: Covered by slough/eschar.",
            signsSymptomsBn = "ধাপ:\n• ধাপ ১: ত্বক লাল কিন্তু চাপ দিলে সাদা হয় না।\n• ধাপ ২: উপরিভাগের চামড়া ক্ষয়/ফোস্কা।\n• ধাপ ৩: চর্বি স্তর পর্যন্ত গভীর ক্ষত।\n• ধাপ ৪: হাড় বা পেশী দেখা যাওয়া।",
            pathophysiologyEn = "External pressure exceeding capillary closing pressure (~32 mmHg) occludes blood flow -> tissue ischemia -> cellular hypoxia & necrosis.",
            pathophysiologyBn = "কৈশিক নালীর চাপের (>৩২ mmHg) চেয়ে বেশি চাপে রক্তপ্রবাহ বন্ধ হয়ে টিস্যু মরে যায়।",
            assessmentEn = "Braden Scale (6–23; <= 18 indicates risk: Sensory, Moisture, Activity, Mobility, Nutrition, Friction/Shear); inspect bony prominences daily; measure wound length x width x depth.",
