            investigationsEn = "Serum albumin/prealbumin (nutrition), CBC, wound culture ONLY if signs of clinical infection (use Levine swab after cleaning, never swab dry exudate!).",
            investigationsBn = "সিরাম অ্যালবুমিন, সিবিসি ও সংক্রমণের লক্ষণ থাকলে ক্ষত পরিষ্কার করে কালচার।",
            medicalManagementEn = "Debridement of necrotic tissue, moist wound dressings (hydrocolloid, foam, alginate), negative-pressure wound therapy (NPWT), systemic antibiotics if cellulitis/osteomyelitis.",
            medicalManagementBn = "মৃত টিস্যু অপসারণ, আধুনিক আর্দ্র ড্রেসিং (হাইড্রোকলয়েড/ফোম) ও সংক্রমণে অ্যান্টিবায়োটিক।",
            nursingManagementEn = "Turn and reposition immobile patients at least every 2 hours; keep HOB <= 30° to prevent shear; float heels off bed with pillows; keep skin clean & dry; NEVER massage reddened bony prominences; provide high-protein, Vit C & Zinc nutrition.",
